// Keep scheduler policy independent of the live MIS bootstrap so module workers can load it.
const teacherSubjects=(p,id)=>p.teachers.find(t=>t.id===id)?.subjectIds||[...new Set(p.activities.filter(a=>a.teacherIds.includes(id)).map(a=>a.subjectId))];
export const defaultYearBands=(t,p)=>{const rows=p?.activities.filter(a=>a.teacherIds.includes(t.id))||[];return ['Early years','Primary','Primary specialist'].includes(t.phase)||rows.length&&rows.every(a=>typeof a.year!=='number'||a.year<=6)?['primary']:['lower','igcse','as','a2'];};
export const teacherLimit=t=>['HOD','HOY'].includes(t.duty)?24:30;
export const teachingBand=y=>y<=6?'primary':y<=9?'lower':y<=11?'igcse':y===12?'as':'a2';
export const isPE=a=>['pe','physical-education'].includes(a.subjectId);
export const isLanguage=a=>['russian','russian-as-a-second-language','uzbek-language'].includes(a.subjectId);
const hours=a=>a.weeklyCount*a.duration;
export function policyInputIssues(p){if(!p.schoolPolicy)return[];const out=[],add=(kind,message,ids=[])=>out.push({kind,message,lessonIds:ids});
 for(const t of p.teachers){const acts=p.activities.filter(a=>a.teacherIds.includes(t.id)),load=(t.committedLoad||0)+acts.reduce((n,a)=>n+hours(a),0);if(acts.length&&load>teacherLimit(t))add('weekly-load',t.name+' has '+load+' periods; '+(t.duty||'Teacher')+' limit is '+teacherLimit(t)+'.',acts.map(a=>a.id));for(const a of acts)if(a.subjectId!=='assembly'&&a.subjectId!=='pshe'&&a.subjectId!=='language-support'&&(!teacherSubjects(p,t.id).includes(a.subjectId)||t.yearBands&&!t.yearBands.includes(teachingBand(a.year))))add('specialist-allocation',t.name+' is not declared for '+a.name+' at this year level.',[a.id]);}
 for(const a of p.activities){if(a.languagePartner){const language=p.activities.find(x=>x.id===a.languagePartner);if(language&&a.teacherIds.some(id=>teacherSubjects(p,id).includes(language.subjectId)))add('language-support',a.name+' needs a non-specialist supervisor.',[a.id]);}if(a.studentIds.length>24)add('class-size',a.name+' has '+a.studentIds.length+' students; maximum 24.',[a.id]);if(isLanguage(a)&&!p.activities.some(b=>b.languagePartner===a.id))add('language-support',a.name+' needs a parallel non-specialist support reservation.',[a.id]);}
 for(const g of p.groups.filter(g=>g.year>=7&&g.year<=9))for(const id of g.studentIds){const pshe=p.activities.filter(a=>a.subjectId==='pshe'&&a.studentIds.includes(id)).reduce((n,a)=>n+hours(a),0);if(pshe!==1){add('pshe-weekly',g.name+' needs one PSHE period per student each week.');break;}}
 return out;
}
export function policyPlacementIssues(ctx,index,lesson,position,ignore){if(!ctx.project.schoolPolicy)return[];const out=[],add=(kind,message,ids=[lesson.id])=>out.push({kind,message,lessonIds:ids,day:position.day,period:position.period});
 if(lesson.subjectId==='assembly'&&(position.day!=='mon'||position.period!=='1'))add('assembly-slot','Assembly must be Monday Period 1.');
 if(isPE(lesson)&&lesson.year>=7&&lesson.year<=11){const day=ctx.project.schoolPolicy.peDays[lesson.year];if(position.day!==day)add('pe-year-day','Year '+lesson.year+' PE must be on '+day+'.');}
 const others=[...index.positions].filter(([id])=>!ignore.has(id));
 for(const [id,pos]of others){const other=ctx.lessonMap.get(id);if(other&&((other.activityId===lesson.languagePartner)||(other.languagePartner===lesson.activityId))&&other.ordinal===lesson.ordinal&&(pos.day!==position.day||pos.period!==position.period))add('language-parallel','Language support must run alongside its language lesson.',[lesson.id,id]);}
 for(const pupil of lesson.studentIds){const matches=others.filter(([id,pos])=>pos.day===position.day&&ctx.lessonMap.get(id)?.subjectId===lesson.subjectId&&ctx.lessonMap.get(id)?.studentIds.includes(pupil)),count=lesson.duration+matches.reduce((n,[id])=>n+ctx.lessonMap.get(id).duration,0);if(count>2){add('daily-subject-limit','A student cannot have more than two periods of the same subject in a day.',[lesson.id,...matches.map(([id])=>id)]);break;}}
 return out;
}
export function doublePreference(ctx,index,ids,pos){if(!ctx.project.schoolPolicy)return 0;const order=ctx.periodOrder.get(pos.period);let score=0;for(const id of ids){const l=ctx.lessonMap.get(id);for(const [other,at]of index.positions){const a=ctx.lessonMap.get(other);if(at.day===pos.day&&a.subjectId===l.subjectId&&a.studentIds.some(s=>l.studentSet.has(s)))score+=Math.abs(ctx.periodOrder.get(at.period)-order)===1?-10:5;}}return score;}
export function distributeDepartmentLoads(project){const p=structuredClone(project);p.placements=Object.fromEntries(Object.entries(p.placements).filter(([,v])=>v.locked));const loads=new Map(p.teachers.map(t=>[t.id,t.committedLoad||0])),bands=new Map(p.teachers.flatMap(t=>Object.entries(t.committedBands||{}).map(([b,n])=>[t.id+'|'+b,n]))),simultaneous=new Map();const ordered=[...p.activities].sort((a,b)=>eligible(a).length-eligible(b).length||hours(b)-hours(a)||a.id.localeCompare(b.id)),unassigned=[];
 function eligible(a){const language=a.languagePartner?p.activities.find(x=>x.id===a.languagePartner):null;return p.teachers.filter(t=>(['assembly','pshe','language-support'].includes(a.subjectId)||teacherSubjects(project,t.id).includes(a.subjectId))&&(!language||!teacherSubjects(project,t.id).includes(language.subjectId))&&(!t.yearBands||t.yearBands.includes(teachingBand(a.year))));}
 for(const a of ordered){const used=a.blockId?(simultaneous.get(a.blockId)||new Set()):new Set(),pool=eligible(a).filter(t=>!used.has(t.id)&&loads.get(t.id)+hours(a)<=teacherLimit(t));pool.sort((x,y)=>(loads.get(x.id)/teacherLimit(x)+(bands.get(x.id+'|'+teachingBand(a.year))||0)/50)-(loads.get(y.id)/teacherLimit(y)+(bands.get(y.id+'|'+teachingBand(a.year))||0)/50)||x.name.localeCompare(y.name));const t=pool[0];if(!t){unassigned.push(a.name);for(const id of a.teacherIds)loads.set(id,(loads.get(id)||0)+hours(a));continue;}a.teacherIds=[t.id];loads.set(t.id,loads.get(t.id)+hours(a));bands.set(t.id+'|'+teachingBand(a.year),(bands.get(t.id+'|'+teachingBand(a.year))||0)+hours(a));if(a.blockId){used.add(t.id);simultaneous.set(a.blockId,used);}}
 for(const a of p.activities){const home=p.teachers.find(t=>t.id===a.teacherIds[0])?.homeRoomId;if(home&&a.roomIds.includes(home))a.roomIds=[home,...a.roomIds.filter(id=>id!==home)];}
 p.staffingReview={at:new Date().toISOString(),unassigned,message:unassigned.length?'Staffing shortages need manager review; existing assignments retained for these classes.':'Allocation balanced within declared subject/year eligibility and weekly limits.'};return p;
}
export function applySchoolPolicy(project){const p=structuredClone(project);p.schoolPolicy={version:1,maxClassSize:24,maxDailySubject:2,peDays:{7:'mon',8:'tue',9:'wed',10:'thu',11:'fri'},doubleAcrossBreaks:true};p.managerWorkflow={reviews:{}};p.subjects=p.subjects.filter(s=>s.id!=='language-support').concat({id:'language-support',name:'Supervised language support',color:'#79817b'});for(const t of p.teachers){t.subjectIds??=teacherSubjects(project,t.id);t.duty??='Teacher';t.yearBands??=defaultYearBands(t,project);}p.placements={};for(const a of p.activities)a.spread=false;
 for(const a of [...p.activities].filter(isLanguage)){if(p.activities.some(b=>b.languagePartner===a.id))continue;let block=p.optionBlocks.find(b=>b.id===a.blockId);if(!block){const bid='language-parallel-'+a.id;a.blockId=bid;block={id:bid,name:a.name+' · parallel support',year:a.year,activityIds:[a.id],studentIds:[...a.studentIds],weeklyCount:a.weeklyCount,duration:a.duration};p.optionBlocks.push(block);}const id=a.id+'-support';p.activities.push({...a,id,name:a.name+' · support reservation',subjectId:'language-support',studentIds:[],groupIds:[],teacherIds:[...a.teacherIds],languagePartner:a.id,nonUzbekOnly:false,roomIds:p.rooms.filter(r=>r.type==='general').map(r=>r.id),supportReservation:true});block.activityIds.push(id);}
 for(const a of p.activities)if(a.subjectId==='assembly'){a.fixedSlots=[{day:'mon',period:'1'}];p.placements[a.id+'#1']={day:'mon',period:'1',roomId:a.roomIds[0],locked:true};}
 return distributeDepartmentLoads(p);
}
export function setLanguageSupport(project,activityId,studentIds){const p=structuredClone(project),source=p.activities.find(a=>a.id===activityId),support=p.activities.find(a=>a.languagePartner===activityId);if(!source||!support)throw Error('Apply the school policy to create the parallel support group first.');const all=new Set([...source.studentIds,...support.studentIds]);if(!Array.isArray(studentIds)||new Set(studentIds).size!==studentIds.length||studentIds.some(id=>!all.has(id))||studentIds.length>24)throw Error('Choose up to 24 students from this language group.');support.studentIds=[...studentIds];source.studentIds=[...all].filter(id=>!studentIds.includes(id));for(const a of [source,support])a.groupIds=p.groups.filter(g=>g.studentIds.some(id=>a.studentIds.includes(id))).map(g=>g.id);if(source.studentIds.length>24)throw Error('Split the language class before assigning more than 24 students.');p.placements={};p.managerWorkflow={reviews:{}};return p;}
